function summarizeWindow(events, nowMs, windowMs, cap) {
  const seen = new Set();
  const qualifying = [];
  const start = nowMs - windowMs;
  const prefix = 'opencode-go/';

  for (const ev of events) {
    if (ev === null || typeof ev !== 'object') continue;

    const id = ev.id;
    if (typeof id === 'string' && id.length > 0) {
      if (seen.has(id)) continue;
      seen.add(id);
    }

    const ts = ev.ts;
    if (typeof ts !== 'number' || !Number.isFinite(ts)) continue;
    if (ts < start || ts > nowMs) continue;
    if (ev.provider !== 'opencode-go') continue;
    if (ev.error) continue;
    if (typeof ev.model !== 'string') continue;
    if (ev.model.toLowerCase().endsWith('-free')) continue;

    qualifying.push(ev);
  }

  let minTs = Infinity;
  const counts = new Map();

  for (const ev of qualifying) {
    if (ev.ts < minTs) minTs = ev.ts;

    let name = ev.model;
    if (name.toLowerCase().startsWith(prefix)) {
      name = name.slice(prefix.length);
    }
    name = name.toLowerCase();
    counts.set(name, (counts.get(name) || 0) + 1);
  }

  const used = qualifying.length;
  const byModel = Object.fromEntries(
    Array.from(counts.keys())
      .sort()
      .map((name) => [name, counts.get(name)])
  );

  return {
    used,
    remaining: Math.max(0, cap - used),
    pct: Math.round((used / cap) * 1000) / 10,
    overCap: used > cap,
    oldestExpiresAt: used === 0 ? null : minTs + windowMs,
    byModel,
  };
}
